#!/usr/bin/env node
/**
 * Auto-generate src/tools/registry.ts by scanning src/tools/*.ts.
 *
 * Conventions:
 *   - A regular tool file `foo.ts` exports `fooTool` (or `<camel>Tool`,
 *     derived from the kebab-case file name). It's added to the
 *     non-factory list.
 *   - A factory tool file `foo.ts` exports `buildFooTool(otherTools)`.
 *     It's appended after the non-factory list and receives that list.
 *     This is how `script` composes every other tool.
 *   - `registry.ts` and `types.ts` are excluded.
 *
 * The generator writes `src/tools/registry.ts` with an AUTO-GENERATED
 * header. CI/`verify` runs it via `prebuild` so a new tool file is
 * picked up automatically; there's a paired drift test in
 * `tests/registry-sync.test.ts` that fails if anyone hand-edits the
 * file and forgets to regenerate.
 */

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const TOOLS_DIR = resolve(__dirname, "..", "src", "tools");
const OUT_FILE = join(TOOLS_DIR, "registry.ts");
const EXCLUDED = new Set(["registry.ts", "types.ts"]);

function kebabToCamel(name) {
  return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

function pascal(s) {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

/**
 * Inspect a tool file. Returns { kind, exportName, importName, fileBase }
 * where `kind` is "tool" (regular) or "factory" (build*Tool).
 */
function inspectTool(file) {
  const fileBase = file.replace(/\.ts$/, "");
  const camel = kebabToCamel(fileBase);
  const source = readFileSync(join(TOOLS_DIR, file), "utf8");
  const factoryName = `build${pascal(camel)}Tool`;
  const toolName = `${camel}Tool`;
  // Factory takes precedence — if both exist, the factory shape wins
  // (it'd be the more elaborate of the two anyway).
  if (new RegExp(`export\\s+function\\s+${factoryName}\\b`).test(source)) {
    return { kind: "factory", exportName: factoryName, fileBase };
  }
  if (new RegExp(`export\\s+const\\s+${toolName}\\b`).test(source)) {
    return { kind: "tool", exportName: toolName, fileBase };
  }
  throw new Error(
    `${file}: expected export \`${toolName}\` (regular tool) or \`${factoryName}\` (factory) — none found. ` +
      "If this file isn't a tool, add it to EXCLUDED in scripts/gen-registry.mjs.",
  );
}

function generate() {
  const files = readdirSync(TOOLS_DIR)
    .filter((f) => f.endsWith(".ts") && !EXCLUDED.has(f))
    .sort();
  const entries = files.map(inspectTool);
  const tools = entries.filter((e) => e.kind === "tool");
  const factories = entries.filter((e) => e.kind === "factory");

  // Sort the ToolDef type import inline with the tool imports by module path
  // rather than pinning it last: pinning breaks biome's import order the moment
  // a tool file sorts after "types.js" (none today, but e.g. a "wait" tool
  // would). The ASCII compare below matches biome only for the all-lowercase
  // specifiers we have; registry-sync.test.ts guards against any drift.
  const imports = entries.map((e) => ({
    path: `./${e.fileBase}.js`,
    line: `import { ${e.exportName} } from "./${e.fileBase}.js";`,
  }));
  imports.push({
    path: "./types.js",
    line: `import type { ToolDef } from "./types.js";`,
  });
  imports.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  const importLines = imports.map((i) => i.line).join("\n");

  const toolListLines = tools.map((t) => `  ${t.exportName},`).join("\n");
  const factoryComposition = factories
    .map((f) => `  ${f.exportName}(everythingElse),`)
    .join("\n");

  const out = `// AUTO-GENERATED by scripts/gen-registry.mjs — DO NOT EDIT BY HAND.
// To add a tool: drop a new file in src/tools/<name>.ts exporting either
// \`<camel>Tool\` (regular) or \`build<Camel>Tool(otherTools)\` (factory),
// then run \`npm run gen:registry\` (or any of prebuild/pretest/predev,
// which re-run it for you).
${importLines}

// biome-ignore lint/suspicious/noExplicitAny: heterogeneous tool shapes
const everythingElse: ToolDef<any>[] = [
${toolListLines}
];

// Factory tools are appended last so they can dispatch into every other
// tool while being unable to invoke themselves (no recursion).
// biome-ignore lint/suspicious/noExplicitAny: heterogeneous tool shapes
export const tools: ToolDef<any>[] = [
  ...everythingElse,
${factoryComposition}
];
`;
  return out;
}

const generated = generate();

// Idempotent: only write when the content actually changed, so editors
// and watch processes don't see a stat bump on every run.
let existing = "";
try {
  existing = readFileSync(OUT_FILE, "utf8");
} catch {
  // no existing file
}
if (existing !== generated) {
  writeFileSync(OUT_FILE, generated);
  console.log(`gen-registry: wrote ${OUT_FILE}`);
} else {
  console.log("gen-registry: up to date");
}
